using System;
using System.Configuration;
using System.Data;
using System.Data.SqlClient;
using FormularioWeb.Models;

namespace FormularioWeb.Data
{
    public class EstudianteRepository
    {
        private readonly string cs=ConfigurationManager.ConnectionStrings["ConexionFormulario"].ConnectionString;
        public DataTable Listar(string filtro){var t=new DataTable();const string sql=@"SELECT e.Id,e.Cedula,e.Nombres,e.Apellidos,e.Correo,e.Telefono,e.Programa,e.Semestre,(SELECT COUNT(*) FROM dbo.InscripcionActividad i WHERE i.EstudianteId=e.Id) AS InscripcionesActivas FROM dbo.Estudiantes e WHERE (@q='' OR e.Cedula LIKE @like OR e.Nombres LIKE @like OR e.Apellidos LIKE @like OR e.Correo LIKE @like) ORDER BY e.Apellidos,e.Nombres";using(var cn=new SqlConnection(cs))using(var cmd=new SqlCommand(sql,cn))using(var da=new SqlDataAdapter(cmd)){cmd.Parameters.Add("@q",SqlDbType.NVarChar,120).Value=filtro??"";cmd.Parameters.Add("@like",SqlDbType.NVarChar,130).Value="%"+(filtro??"")+"%";da.Fill(t);}return t;}
        public void Guardar(EstudianteDto e){using(var cn=new SqlConnection(cs))using(var cmd=new SqlCommand(e.Id==0?@"INSERT dbo.Estudiantes(Cedula,CodigoRegistro,Nombres,Apellidos,Correo,Telefono,Programa,Semestre,Participacion,Jornada,TemasInteres,Comentarios,AceptaTratamiento,FechaRegistro) VALUES(@ced,@cod,@nom,@ape,@mail,@tel,@prog,@sem,N'Estudiante',N'No aplica',NULL,NULL,1,SYSDATETIME())":@"UPDATE dbo.Estudiantes SET Cedula=@ced,Nombres=@nom,Apellidos=@ape,Correo=@mail,Telefono=@tel,Programa=@prog,Semestre=@sem WHERE Id=@id",cn)){cmd.Parameters.Add("@ced",SqlDbType.VarChar,20).Value=e.Cedula;cmd.Parameters.Add("@nom",SqlDbType.NVarChar,100).Value=e.Nombres;cmd.Parameters.Add("@ape",SqlDbType.NVarChar,100).Value=e.Apellidos;cmd.Parameters.Add("@mail",SqlDbType.NVarChar,150).Value=e.Correo;cmd.Parameters.Add("@tel",SqlDbType.VarChar,20).Value=e.Telefono;cmd.Parameters.Add("@prog",SqlDbType.NVarChar,100).Value=e.Programa;cmd.Parameters.Add("@sem",SqlDbType.Int).Value=e.Semestre;if(e.Id==0)cmd.Parameters.Add("@cod",SqlDbType.VarChar,30).Value="ADM-"+Guid.NewGuid().ToString("N").Substring(0,24);else cmd.Parameters.Add("@id",SqlDbType.Int).Value=e.Id;cn.Open();cmd.ExecuteNonQuery();}}
        public EstudianteDto Obtener(int id){using(var cn=new SqlConnection(cs))using(var cmd=new SqlCommand("SELECT Id,Cedula,Nombres,Apellidos,Correo,Telefono,Programa,Semestre FROM dbo.Estudiantes WHERE Id=@id",cn)){cmd.Parameters.Add("@id",SqlDbType.Int).Value=id;cn.Open();using(var r=cmd.ExecuteReader()){if(!r.Read())return null;return new EstudianteDto{Id=r.GetInt32(0),Cedula=r.GetString(1),Nombres=r.GetString(2),Apellidos=r.GetString(3),Correo=r.GetString(4),Telefono=r.GetString(5),Programa=r.GetString(6),Semestre=r.GetInt32(7)};}}}
        public void Eliminar(int id){using(var cn=new SqlConnection(cs)){cn.Open();using(var tx=cn.BeginTransaction(IsolationLevel.Serializable)){try{using(var check=new SqlCommand("SELECT COUNT(*) FROM dbo.Estudiantes WITH(UPDLOCK,HOLDLOCK) WHERE Id=@id",cn,tx)){check.Parameters.Add("@id",SqlDbType.Int).Value=id;if((int)check.ExecuteScalar()==0)throw new InvalidOperationException("No se encontró el estudiante.");}foreach(string table in new[]{"InscripcionActividad","ResenaActividad","CuentaEstudiante"})using(var cmd=new SqlCommand("DELETE FROM dbo."+table+" WHERE EstudianteId=@id",cn,tx)){cmd.Parameters.Add("@id",SqlDbType.Int).Value=id;cmd.ExecuteNonQuery();}using(var cmd=new SqlCommand("DELETE dbo.Estudiantes WHERE Id=@id",cn,tx)){cmd.Parameters.Add("@id",SqlDbType.Int).Value=id;cmd.ExecuteNonQuery();}tx.Commit();}catch{tx.Rollback();throw;}}}}
    }
}
